#!/usr/bin/env bash
set -euo pipefail
dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cp -r "$dir/fixtures"/. .

# Commit everything with a date BEFORE the "Generated by /vibe:sync on
# 2024-02-01" line in .vibe/index.md, and leave the tree clean, so neither
# `git log --since=2024-02-01` nor `git status --porcelain` reports anything.
git init -q -b main
git config user.email "eval@example.com"
git config user.name "Eval Fixture"
git add -A
GIT_AUTHOR_DATE="2024-01-15T09:00:00" GIT_COMMITTER_DATE="2024-01-15T09:00:00" \
  git commit -q -m "chore: initial commit"
